    pub bits: usize,
}

pub fn encode(data: &[u8], codes: &HashMap<u8, Vec<bool>>) -> Encoded {
    let mut bits: Vec<bool> = Vec::new();
    for b in data {
        bits.extend_from_slice(&codes[b]);
    }

    let mut bytes = vec![0u8; bits.len().div_ceil(8)];
    for (i, &bit) in bits.iter().enumerate() {
        if bit {
            bytes[i / 8] |= 1 << (7 - i % 8);
        }
    }
    Encoded { bytes }
}

